"""The `.cargo-checksum.json` of a vendored crate, regenerated by a tool and never by hand.

Cargo checks every file of a vendored crate against this file, which `cargo vendor` writes as one line,
no trailing newline, `{"files":{<path>:<sha256>, ...},"package":<sha256 of the published crate>}`, the paths
sorted. A change to a vendored crate (a backport) changes the hashes of the files it touches and nothing
else, so the line is derived from the files: `render` is the one writer of its bytes.

    python tools/regen_checksums.py <crate dir>                      rewrite it from the files on disk
    python tools/regen_checksums.py <crate dir> --check <file>       compare, write nothing

Bytes in, bytes out: files are read in binary mode, so a checkout that converts line endings must not be
the source of the hashes (the replay reads blobs, not a working tree).
"""
import hashlib
import json
import os
import sys

CHECKSUM = ".cargo-checksum.json"


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def render(old: dict, files: dict) -> bytes:
    """The bytes of the file: `old` is its parsed previous content (the `package` hash and any other key stay,
    in their order), `files` maps each path of the crate to its sha256."""
    new = dict(old)
    new["files"] = dict(sorted(files.items()))
    return json.dumps(new, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def update(old_bytes: bytes, changes: dict) -> bytes:
    """The file after a change: `changes` maps a path of the crate to the sha256 of its new content, or to None when
    the file is gone. Every other entry is kept as it is."""
    old = json.loads(old_bytes.decode("utf-8"))
    files = dict(old["files"])
    for path, digest in changes.items():
        if digest is None:
            files.pop(path, None)
        else:
            files[path] = digest
    return render(old, files)


def disagreements(old_bytes: bytes, current: dict) -> list:
    """What differs between a checksum file and the files it describes (`current`: path to sha256): the paths
    whose hash is another, listed and missing, present and unlisted. [] when it is exactly what the tool writes."""
    old = json.loads(old_bytes.decode("utf-8"))["files"]
    found = ["%s: hash differs" % p for p in sorted(current) if p in old and old[p] != current[p]]
    found += ["%s: listed, file missing" % p for p in sorted(old) if p not in current]
    found += ["%s: file not listed" % p for p in sorted(current) if p not in old]
    return found


def read_dir(crate: str) -> dict:
    files = {}
    for root, _dirs, names in os.walk(crate):
        for name in names:
            path = os.path.join(root, name)
            rel = os.path.relpath(path, crate).replace(os.sep, "/")
            if rel != CHECKSUM:
                with open(path, "rb") as handle:
                    files[rel] = sha256(handle.read())
    return files


def regenerate_dir(crate: str) -> bytes:
    """The bytes of the crate's checksum file as the files on disk say it."""
    with open(os.path.join(crate, CHECKSUM), "rb") as handle:
        old = json.loads(handle.read().decode("utf-8"))
    return render(old, read_dir(crate))


def main(argv: list) -> int:
    if not argv or argv[0].startswith("-"):
        print(__doc__)
        return 2
    crate = argv[0]
    out = regenerate_dir(crate)
    if "--check" in argv:
        with open(argv[argv.index("--check") + 1], "rb") as handle:
            expected = handle.read().rstrip(b"\n")
        print("%s %s" % (os.path.basename(os.path.abspath(crate)), "IDENTICAL" if out == expected else "DIFFERENT"))
        return 0 if out == expected else 1
    with open(os.path.join(crate, CHECKSUM), "wb") as handle:
        handle.write(out)
    print("%s rewritten" % os.path.basename(os.path.abspath(crate)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
